INSERT INTO "personalization"."occupation_data" ("occupation_data_id", "onetsoc_code", "title", "description", "created_at", "updated_at")
VALUES
('62abee33-7992-52dc-b051-b6bed19202e3', '11-3021.00', 'Computer and Information Systems Managers', 'Plan, direct, or coordinate activities in such fields as electronic data processing, information systems, systems analysis, and computer programming.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('6daba5ff-aff8-5cf7-8ed9-eb539a47da3e', '15-1211.00', 'Computer Systems Analysts', 'Analyze science, engineering, business, and other data processing problems to develop and implement solutions to complex applications problems, system administration issues, or network concerns. Perform systems management and integration functions, improve existing computer systems, and review computer system capabilities, workflow, and schedule limitations. May analyze or recommend commercially available software.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('b03b5045-e6ac-5aa4-b6f3-1250c2a0a5f2', '15-1211.01', 'Health Informatics Specialists', 'Apply knowledge of nursing and informatics to assist in the design, development, and ongoing modification of computerized health care systems. May educate staff and assist in problem solving to promote the implementation of the health care system.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('141ed81c-ecba-533c-818e-f9efba9622ba', '15-1212.00', 'Information Security Analysts', 'Plan, implement, upgrade, or monitor security measures for the protection of computer networks and information. Assess system vulnerabilities for security risks and propose and implement risk mitigation strategies. May ensure appropriate security controls are in place that will safeguard digital files and vital electronic infrastructure. May respond to computer security breaches and viruses.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('55e3870e-a5bc-5bf6-a934-801a089ba1a7', '15-1221.00', 'Computer and Information Research Scientists', 'Conduct research into fundamental computer and information science as theorists, designers, or inventors. Develop solutions to problems in the field of computer hardware and software.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('bdb9f264-e782-51b6-99fd-781c3a045ecf', '15-1231.00', 'Computer Network Support Specialists', 'Analyze, test, troubleshoot, and evaluate existing network systems, such as local area networks (LAN), wide area networks (WAN), cloud networks, servers, and other data communications networks. Perform network maintenance to ensure networks operate correctly with minimal interruption.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('6af221cf-8ea3-5906-a818-398ad670cd76', '15-1232.00', 'Computer User Support Specialists', 'Provide technical assistance to computer users. Answer questions or resolve computer problems for clients in person, via telephone, or electronically. May provide assistance concerning the use of computer hardware and software, including printing, installation, word processing, electronic mail, and operating systems.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('031b2c9f-a028-59b7-842a-cf2e11c034ab', '15-1241.00', 'Computer Network Architects', 'Design and implement computer and information networks, such as local area networks (LAN), wide area networks (WAN), intranets, extranets, and other data communications networks. Perform network modeling, analysis, and planning, including analysis of capacity needs for network infrastructures. May also design network and computer security measures. May research and recommend network and data communications hardware and software.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('b69088e7-091a-5c57-ace5-43a1d2fc6309', '15-1241.01', 'Telecommunications Engineering Specialists', 'Design or configure wired, wireless, and satellite communications systems for voice, video, and data services. Supervise installation, service, and maintenance.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('a2ea0ced-8114-5f02-b428-6fc3e26d5316', '15-1242.00', 'Database Administrators', 'Administer, test, and implement computer databases, applying knowledge of database management systems. Coordinate changes to computer databases. Identify, investigate, and resolve database performance issues, database capacity, and database scalability. May plan, coordinate, and implement security measures to safeguard computer databases.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('c4ccae66-ffad-5ae6-85b7-4e69a128ccfd', '15-1243.00', 'Database Architects', 'Design strategies for enterprise databases, data warehouse systems, and multidimensional networks. Set standards for database operations, programming, query processes, and security. Model, design, and construct large relational databases or data warehouses. Create and optimize data models for warehouse infrastructure and workflow. Integrate new systems with existing warehouse structure and refine system performance and functionality.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('4cbc80db-aa62-5162-b155-77ea86557680', '15-1243.01', 'Data Warehousing Specialists', 'Design, model, or implement corporate data warehousing activities. Program and configure warehouses of database information and provide support to warehouse users.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('9f179226-68e2-5152-aa2a-aa4e506d0c18', '15-1244.00', 'Network and Computer Systems Administrators', 'Install, configure, and maintain an organization''s local area network (LAN), wide area network (WAN), data communications network, operating systems, and physical and virtual servers. Perform system monitoring and verify the integrity and availability of hardware, network, and server resources and systems. Review system and application logs and verify completion of scheduled jobs, including system backups. Analyze network and server resource consumption and control user access. Install and upgrade software and maintain software licenses. May assist in network modeling, analysis, planning, and coordination between network and data communications hardware and software.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('8bc13a99-1695-5df8-a234-010713bd7f3e', '15-1251.00', 'Computer Programmers', 'Create, modify, and test the code and scripts that allow computer applications to run. Work from specifications drawn up by software and web developers or other individuals. May develop and write computer programs to store, locate, and retrieve specific documents, data, and information.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('5d49ec6d-296d-554d-b123-72878c33a797', '15-1252.00', 'Software Developers', 'Research, design, and develop computer and network software or specialized utility programs. Analyze user needs and develop software solutions, applying principles and techniques of computer science, engineering, and mathematical analysis. Update software or enhance existing software capabilities. May work with computer hardware engineers to integrate hardware and software systems, and develop specifications and performance requirements. May maintain databases within an application area, working individually or coordinating database development as part of a team.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('8199c3df-cc92-5daa-9b6c-406996dcc81b', '15-1253.00', 'Software Quality Assurance Analysts and Testers', 'Develop and execute software tests to identify software problems and their causes. Test system modifications to prepare for implementation. Document software and application defects using a bug tracking system and report defects to software or web developers. Create and maintain databases of known defects. May participate in software design reviews to provide input on functional requirements, operational characteristics, product designs, and schedules.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('14528658-af72-50c9-8f75-a62f734eff2c', '15-1254.00', 'Web Developers', 'Develop and implement websites, web applications, application databases, and interactive web interfaces. Evaluate code to ensure that it is properly structured, meets industry standards, and is compatible with browsers and devices. Optimize website performance, scalability, and server-side code and processes. May develop website infrastructure and integrate websites with other computer applications.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('80e823af-2603-51e1-9e2b-2cd1e0ee2c7e', '15-1255.00', 'Web and Digital Interface Designers', 'Design digital user interfaces or websites. Develop and test layouts, interfaces, functionality, and navigation menus to ensure compatibility and usability across browsers or devices. May use web framework applications as well as client-side code and processes. May evaluate web design following web and accessibility standards, and may analyze web use metrics and optimize websites for marketability and search engine ranking. May design and test interfaces that facilitate the human-computer interaction and maximize the usability of digital devices, websites, and software with a focus on aesthetics and design. May create graphics used in websites and manage website content and links.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('f24f4577-cc37-5edd-bcb7-0ee767d34183', '15-1255.01', 'Video Game Designers', 'Design core features of video games. Specify innovative game and role-play mechanics, story lines, and character biographies. Create and maintain design documentation. Guide and collaborate with production staff to produce games as designed.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('91cffa4c-94a7-5e58-92ad-1a5004ad441f', '15-1299.01', 'Web Administrators', 'Manage web environment design, deployment, development and maintenance activities. Perform testing and quality assurance of web sites and web applications.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('342fb12e-1f76-51b2-a537-ab59b4001ed0', '15-1299.03', 'Document Management Specialists', 'Implement and administer enterprise-wide document management systems and related procedures that allow organizations to capture, store, retrieve, share, and destroy electronic records and documents.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('08b956f3-4ed0-5f5c-a4b5-45f33797da88', '15-1299.04', 'Penetration Testers', 'Evaluate network system security by conducting simulated internal and external cyberattacks using adversary tools and techniques. Attempt to breach and exploit critical systems and gain access to sensitive information to assess system security.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('f25b238d-502a-567f-9136-cd92d8b7c255', '15-1299.05', 'Information Security Engineers', 'Develop and oversee the implementation of information security procedures and policies. Build, maintain and upgrade security technology, such as firewalls, for the safe use of computer networks and the transmission and retrieval of information. Design and implement appropriate security controls to identify vulnerabilities and protect digital files and electronic infrastructures. Monitor and respond to computer security breaches, viruses, and intrusions, and perform forensic investigation. May oversee the assessment of information security systems.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('f75b66d7-e225-56c9-b066-556a6188efb5', '15-1299.06', 'Digital Forensics Analysts', 'Conduct investigations on computer-based crimes establishing documentary or physical evidence, such as digital media and logs associated with cyber intrusion incidents. Analyze digital evidence and investigate computer security incidents to derive information in support of system and network vulnerability mitigation. Preserve and present computer-related evidence in support of criminal, fraud, counterintelligence, or law enforcement investigations.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('03cf95f4-26f0-5dab-8e3c-23f117c0d1d8', '15-1299.07', 'Blockchain Engineers', 'Maintain and support distributed and decentralized blockchain-based networks or block-chain applications such as cryptocurrency exchange, payment processing, document sharing, and digital voting. Design and deploy secure block-chain design patterns and solutions over geographically distributed networks using advanced technologies. May assist with infrastructure setup and testing for application transparency and security.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('351cc322-960f-5629-bd29-67e28fb39271', '15-1299.08', 'Computer Systems Engineers/Architects', 'Design and develop solutions to complex applications problems, system administration issues, or network concerns. Perform systems management and integration functions.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('c252b2ee-f400-5f46-a07c-c053a08fa5c0', '15-1299.09', 'Information Technology Project Managers', 'Plan, initiate, and manage information technology (IT) projects. Lead and guide the work of technical staff. Serve as liaison between business and technical aspects of projects. Plan project stages and assess business implications for each stage. Monitor progress to assure deadlines, standards, and cost targets are met.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('c6e94bd7-84bb-55c8-8ac1-6c957fb9280b', '15-2051.00', 'Data Scientists', 'Develop and implement a set of techniques or analytics applications to transform raw data into meaningful information using data-oriented programming languages and visualization software. Apply data mining, data modeling, natural language processing, and machine learning to extract and analyze information from large structured and unstructured datasets. Visualize, interpret, and report data findings. May create dynamic data reports.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('2ea54e49-2fdc-57ff-a626-425721c28ce0', '15-2051.01', 'Business Intelligence Analysts', 'Produce financial and market intelligence by querying data repositories and generating periodic reports. Devise methods for identifying data patterns and trends in available information sources.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('4df3b23b-71c8-564e-978b-fba9d85f4b61', '15-2051.02', 'Clinical Data Managers', 'Apply knowledge of health care and database management to analyze clinical data, and to identify and report trends.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('1e4abd44-0571-5a82-86ef-af64dba88903', '15-2099.01', 'Bioinformatics Technicians', 'Apply principles and methods of bioinformatics to assist scientists in areas such as pharmaceuticals, medical technology, biotechnology, computational biology, proteomics, computer information science, biology and medical informatics. Apply bioinformatics tools to visualize, analyze, manipulate or interpret molecular data. May build and maintain databases for processing and analyzing genomic or other biological information.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('2120642e-f59d-5200-a965-249cd7f844d7', '17-2061.00', 'Computer Hardware Engineers', 'Research, design, develop, or test computer or computer-related equipment for commercial, industrial, military, or scientific use. May supervise the manufacturing and installation of computer or computer-related equipment and components.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('9e58ea59-e104-5b80-b634-5a3c7c4b129e', '17-2199.05', 'Mechatronics Engineers', 'Research, design, develop, or test automation, intelligent systems, smart devices, or industrial systems control.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('23f2396e-3fa0-5637-aa5b-ecce91aec267', '17-2199.06', 'Microsystems Engineers', 'Research, design, develop, or test microelectromechanical systems (MEMS) devices.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('b00fd1a4-171f-5264-9982-9366a1f45e3d', '17-2199.08', 'Robotics Engineers', 'Research, design, develop, or test robotic applications.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('782dab9f-2c5a-5ac3-bf85-afee4c1e442f', '17-2199.09', 'Nanosystems Engineers', 'Design, develop, or supervise the production of materials, devices, or systems of unique molecular or macromolecular composition, applying principles of nanoscale physics and electrical, chemical, or biological engineering.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('ebc6349a-a0da-5044-8964-e19b70efbd9e', '17-3024.01', 'Robotics Technicians', 'Build, install, test, or maintain robotic equipment or related automated production systems.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('8cec5324-b4ee-5633-9659-52d09efd0683', '19-1029.01', 'Bioinformatics Scientists', 'Conduct research using bioinformatics theory and methods in areas such as pharmaceuticals, medical technology, biotechnology, computational biology, proteomics, computer information science, biology and medical informatics. May design databases and develop algorithms for processing and analyzing genomic information, or other biological information.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('2ea56f4b-cc07-502d-b509-dc588c114146', '25-1021.00', 'Computer Science Teachers, Postsecondary', 'Teach courses in computer science. May specialize in a field of computer science, such as the design and function of computers or operations and research analysis. Includes both teachers primarily engaged in teaching and those who do a combination of teaching and research.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz);
