('4eb1c952-724b-5729-8a72-46bb73615aef', '4.A.1.a.1.I10', '4.A.1.a.1', 'Getting Information', 'Observing, receiving, and otherwise obtaining information from all relevant sources.', 'Investigate the environmental impact of industrial or development activities.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('6d40da00-9393-5e68-a162-e83819769c82', '4.A.1.a.1.I14', '4.A.1.a.1', 'Getting Information', 'Observing, receiving, and otherwise obtaining information from all relevant sources.', 'Collect data about consumer needs or opinions.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('db022049-0c97-58a1-b26a-186f5f289603', '4.A.1.a.1.I16', '4.A.1.a.1', 'Getting Information', 'Observing, receiving, and otherwise obtaining information from all relevant sources.', 'Research biological or ecological phenomena.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('3012bb12-017d-57ec-b58e-34b4a88a4d82', '4.A.1.a.1.I20', '4.A.1.a.1', 'Getting Information', 'Observing, receiving, and otherwise obtaining information from all relevant sources.', 'Research technology designs or applications.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('c7d921fa-4c5a-5863-a2e0-7d6f2ada5f8a', '4.A.1.a.1.I22', '4.A.1.a.1', 'Getting Information', 'Observing, receiving, and otherwise obtaining information from all relevant sources.', 'Investigate organizational or operational problems.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('500d6e92-74f1-54e5-b76f-26ee7f83657e', '4.A.1.a.2.I02', '4.A.1.a.2', 'Monitoring Processes, Materials, or Surroundings', 'Monitoring and reviewing information from materials, events, or the environment, to detect or assess problems.', 'Monitor operations to ensure adequate performance.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('764dae47-b734-55db-9de8-111aad83c6e0', '4.A.1.a.2.I03', '4.A.1.a.2', 'Monitoring Processes, Materials, or Surroundings', 'Monitoring and reviewing information from materials, events, or the environment, to detect or assess problems.', 'Monitor financial data or activities.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('8687ae35-e9d6-5380-ae23-dea6a402360d', '4.A.1.a.2.I10', '4.A.1.a.2', 'Monitoring Processes, Materials, or Surroundings', 'Monitoring and reviewing information from materials, events, or the environment, to detect or assess problems.', 'Monitor operation of computer or information technologies.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('d0f529ed-21c7-57ed-aaa3-d28447847701', '4.A.1.a.2.I11', '4.A.1.a.2', 'Monitoring Processes, Materials, or Surroundings', 'Monitoring and reviewing information from materials, events, or the environment, to detect or assess problems.', 'Monitor operations to ensure compliance with regulations or standards.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('07244510-908f-5a2f-ad84-06ec1a938c2a', '4.A.1.b.1.I02', '4.A.1.b.1', 'Identifying Objects, Actions, and Events', 'Identifying information by categorizing, estimating, recognizing differences or similarities, and detecting changes in circumstances or events.', 'Identify business or organizational opportunities.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
('29cb6585-ac4a-5013-a276-adbc4100f7cc', '4.A.1.b.2.I05', '4.A.1.b.2', 'Inspecting Equipment, Structures, or Materials', 'Inspecting equipment, structures, or materials to identify the cause of errors or other problems or defects.', 'Inspect facilities or equipment.', '2026-03-14T10:36:54+00:00'::timestamptz, '2026-03-14T10:36:54+00:00'::timestamptz),
